def load() -> pd.DataFrame:
    lines = []
    with open('data/astronomy/input/omni2_low_res/omni2.text', 'r') as f:
        lines = f.readlines()
    relevant = []
    capture = False
    for i, line in enumerate(lines):
        if 'COLUMN' in line.upper() or 'field' in line.lower() or 'column' in line.lower():
            capture = True
        if capture:
            relevant.append(line.rstrip())
        if capture and len(relevant) > 300:
            break
    return pd.DataFrame({'line': relevant})

